#[test]
fn legacy_sql_is_exact() {
    let leaf = || {
        HopExpr::Pred(crate::iq::HopRelation {
            source: LogicalSource::Table("edge".into()),
            subj_col: "s".into(),
            obj_col: "o".into(),
        })
    };
    let mut i = 0;
    for dialect in [Dialect::Sqlite, Dialect::Postgres, Dialect::MySql] {
        for kind in [
            PathKind::One,
            PathKind::ZeroOrOne,
            PathKind::OneOrMore,
            PathKind::ZeroOrMore,
        ] {
            assert_eq!(
                prelude(
                    &PathClosure {
                        alias: 7,
                        kind,
                        hop: leaf()
                    },
                    7,
                    dialect,
                    &ColumnCatalog::default(),
                    SourceWork::new(None)
                )
                .unwrap(),
                LEGACY[i]
            );
            i += 1;
        }
        for hop in [
            HopExpr::Inverse(Box::new(leaf())),
            HopExpr::Seq(Box::new(leaf()), Box::new(leaf())),
            HopExpr::Alt(vec![leaf(), leaf()]),
            HopExpr::Nps(vec![leaf(), leaf()]),
        ] {
            assert_eq!(
                prelude(
                    &PathClosure {
                        alias: 7,
                        kind: PathKind::One,
                        hop
                    },
                    7,
                    dialect,
                    &ColumnCatalog::default(),
                    SourceWork::new(None)
                )
                .unwrap(),
                LEGACY[i]
            );
            i += 1;
        }
    }
    assert_eq!(i, LEGACY.len());
}
